    roundResultEl.textContent = 'You win!';
  } else {
    scores.computer++;
    computerScoreEl.textContent = scores.computer;
    roundResultEl.textContent = 'You lose!';
  }
}
document.querySelectorAll('.choice-btn').forEach(b => b.addEventListener('click', () => playRound(b.dataset.choice)));

