:root {
  --bg-color: #0b0f19;
  --card-bg: #151c2e;
  --primary: #a855f7;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border: #232f48;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}
.game-container {
  background-color: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  width: 100%;
  max-width: 500px;
  padding: 2rem;
  text-align: center;
}
.game-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 1.25rem;
}
.score-board {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  background: #0b0f19;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 0.75rem 1.5rem;
  width: fit-content;
  margin: 0 auto;
}
.score-card { display: flex; flex-direction: column; }
.score-label { font-size: 0.75rem; color: var(--text-muted); }
.score-value { font-size: 1.75rem; font-weight: 800; }
.score-divider { font-size: 1.5rem; color: var(--border); }
.choices-container {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2rem;
}
.choice-btn {
  background: #0b0f19;
  border: 2px solid var(--border);
  border-radius: 1rem;
  width: 5rem;
  height: 5rem;
  font-size: 2.25rem;
  cursor: pointer;
}
.battle-display {
  background: #0b0f19;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}
.hand-box { display: flex; flex-direction: column; align-items: center; gap: 0.5rem; flex: 1; }
.hand-label { font-size: 0.7rem; color: var(--text-muted); }
.hand-icon { font-size: 2.5rem; }
.status-box { flex: 1.2; }
.round-result { font-size: 0.95rem; font-weight: 600; }
.game-footer { border-top: 1px solid var(--border); padding-top: 1.25rem; }
.reset-button {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  padding: 0.5rem 1.25rem;
  border-radius: 0.5rem;
  cursor: pointer;
}

const choices = ['rock', 'paper', 'scissors'];
const icons = { rock: '✊', paper: '✋', scissors: '✌️' };
const playerScoreEl = document.getElementById('player-score');
const computerScoreEl = document.getElementById('computer-score');
const playerHandEl = document.getElementById('player-hand');
const computerHandEl = document.getElementById('computer-hand');
const roundResultEl = document.getElementById('round-result');
const resetBtn = document.getElementById('reset-btn');
let scores = { player: 0, computer: 0 };

function playRound(playerChoice) {
  const computerChoice = choices[Math.floor(Math.random() * choices.length)];
  playerHandEl.textContent = icons[playerChoice];
  computerHandEl.textContent = icons[computerChoice];
  if (playerChoice === computerChoice) {
    roundResultEl.textContent = "It's a tie!";
  } else if ((playerChoice === 'rock' && computerChoice === 'scissors') || (playerChoice === 'paper' && computerChoice === 'rock') || (playerChoice === 'scissors' && computerChoice === 'paper')) {
    scores.player++;
    playerScoreEl.textContent = scores.player;
    roundResultEl.textContent = `You win! ${playerChoice} beats ${computerChoice}.`;
  } else {
    scores.computer++;
    computerScoreEl.textContent = scores.computer;
    roundResultEl.textContent = `You lose! ${computerChoice} beats ${playerChoice}.`;
  }
}
document.querySelectorAll('.choice-btn').forEach(btn => btn.addEventListener('click', () => playRound(btn.dataset.choice)));
resetBtn.addEventListener('click', () => {
  scores = { player: 0, computer: 0 };
  playerScoreEl.textContent = '0';
  computerScoreEl.textContent = '0';
  roundResultEl.textContent = 'Choose your move to start!';
});
